import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';
import {createIssue} from '../../server/src/modules/work/issues.js';
import {createComment} from '../../server/src/modules/work/comments.js';
import {createRelation} from '../../server/src/modules/work/relations.js';
async function browser(mode) {
  const server=await testServer();let child;
  try {
    const api=server.agent();
    const auth=await api('POST','/auth/signup',{name:'Browser owner',email:'work-browser@example.test',password:'correct-horse-battery'});
    const user=auth.data.user,req={user};
    const org=(await api('POST','/orgs',{name:'Work browser'})).data.organization;
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'WEB',name:'Browser project'})).data.project;
    const cross=(await api('POST','/orgs/'+org.id+'/projects',{key:'CROSS',name:'Cross project'})).data.project;
    const db=server.ctx.db,time=server.ctx.now();
    server.ctx.transaction(()=>{
      for(let n=0;n<212;n++){
        const id='browser-person-'+n;
        db.prepare('INSERT INTO users (id,email,name,password_hash,created_at,updated_at) SELECT ?,?,?,password_hash,?,? FROM users WHERE id=?').run(id,id+'@example.test','Person '+String(n).padStart(3,'0'),time,time,user.id);
        db.prepare('INSERT INTO memberships VALUES (?,?,?,?,?)').run(org.id,id,'member',time,time);
        db.prepare('INSERT INTO labels VALUES (?,?,?,?,?,?)').run('browser-label-'+n,project.id,'Label '+String(n).padStart(3,'0'),'#123456',time,time);
      }
    });
    const parent=createIssue(server.ctx,req,project.id,{title:'Original older parent'});
    const candidates=[];for(let n=0;n<213;n++)candidates.push(createIssue(server.ctx,req,project.id,{title:'Candidate '+String(n).padStart(3,'0')}));
    const issue=createIssue(server.ctx,req,project.id,{title:'Primary issue',description:'<script>window.workInjected=true</script>',assigneeId:'browser-person-210',parentId:parent.id,labelIds:['browser-label-0']});
    const other=createIssue(server.ctx,req,project.id,{title:'Other route issue'});
    const target=createIssue(server.ctx,req,cross.id,{title:'Cross organization work reference'});
    const comments=[];for(let n=0;n<24;n++)comments.push(createComment(server.ctx,req,issue.id,{body:'Comment '+String(n).padStart(2,'0')}));
    for(const candidate of candidates.slice(0,24))createRelation(server.ctx,req,issue.id,{kind:'relates',targetIssueId:candidate.id});
    const settings={mode,url:server.url,cookie:auth.cookie,projectId:project.id,crossId:cross.id,issueId:issue.id,otherId:other.id,parentId:parent.id,targetId:target.id,assigneeId:'browser-person-209',lastLabel:'browser-label-211'};
    const result=await new Promise((resolve,reject)=>{
      child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./issue-browser.py',import.meta.url)),JSON.stringify(settings)],{detached:true});
      let stdout='',stderr='';const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('Work browser exceeded 55 seconds'));},55000);
      child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});
    });
    assert.equal(result.code,0,result.stderr);assert.equal(JSON.parse(result.stdout.trim()).ok,true);
    if(mode==='editor'){
      const saved=(await api('GET','/issues/'+issue.id)).data.issue;
      assert.equal(saved.title,'Local browser draft');assert.equal(saved.priority,4);assert.equal(saved.assigneeId,'browser-person-209');assert.equal(saved.parentId,null);
      assert.ok(saved.mentionedUserIds.includes('browser-person-210'));assert.ok(saved.labels.some(label=>label.id==='browser-label-211'));
    }
  }finally{if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}await server.close();}
}
for(const mode of ['editor','discussion','navigation','markdown','toolbar'])test('pinned browser work '+mode+' uses actual complete controls and preserves resource state',{timeout:65000},()=>browser(mode));
